-- Generated by scripts/build_compiled.py from src/fraudrules/rules/money-mule/mu-002-fan-in-new-account.yaml. Do not edit.
-- MU-002 New personal account credited by many unrelated individuals
SELECT
  'MU-002' AS rule_id,
  'transactions' AS anchor_table,
  a.id AS anchor_id
FROM transactions AS a
JOIN transactions AS b
  ON b.account_id = a.account_id AND b.ts <= a.ts AND b.ts > a.ts - 604800
WHERE
  (
    a.direction = 'in'
    AND a.counterparty_type = 'individual'
    AND a.channel IN ('ach', 'wire', 'rtp', 'p2p')
    AND a.ts < (
      a.account_opened_ts + 5184000
    )
  )
  AND (
    b.direction = 'in'
    AND b.counterparty_type = 'individual'
    AND b.channel IN ('ach', 'wire', 'rtp', 'p2p')
  )
GROUP BY
  a.id
HAVING
  COUNT(DISTINCT b.counterparty_id) >= 5;
